export type Item = { sku: string; price: number; qty: number };
export type Coupon = { kind: "percent"; value: number; maxOff?: number } | { kind: "fixed"; value: number };

const TAX: Record<string, number> = { CA: 0.0725, NY: 0.04, OR: 0 };

// Round dollars to integer cents. The 1e-7 nudge makes binary-float halves (96.525) round up.
const toCents = (dollars: number): number => Math.round(dollars * 100 + 1e-7);

/** Subtotal in dollars. */
export function subtotal(items: Item[]): number {
  return items.reduce((s, i) => s + i.price * i.qty, 0);
}

/** Bulk pricing: 10% off a line when qty >= 10. */
export function lineTotal(i: Item): number {
  return i.qty >= 10 ? i.price * i.qty * 0.9 : i.price * i.qty;
}

export function applyCoupon(amount: number, c?: Coupon): number {
  if (!c) return amount;
  if (c.kind === "fixed") return Math.max(0, amount - c.value);
  const off = amount * (c.value / 100);
  return amount - (c.maxOff === undefined ? off : Math.min(off, c.maxOff));
}

export function tax(amount: number, region: string): number {
  const rate = TAX[region];
  if (rate === undefined) throw new Error(`unknown region: ${region}`);
  return amount * rate;
}

/** Final total, rounded to cents. */
export function total(items: Item[], region: string, c?: Coupon): number {
  const baseCents = items.reduce((s, i) => s + toCents(lineTotal(i)), 0);
  const discountedCents = toCents(applyCoupon(baseCents / 100, c));
  const taxCents = toCents(tax(discountedCents / 100, region));
  return (discountedCents + taxCents) / 100;
}
